const burgerEl = document.querySelector(".burger-btn");

function burgerToggle() {
    const navEl = burgerEl
        .closest(".header__wrapper")
        .querySelector(".nav__list");
    burgerEl.classList.toggle("burger-btn--active");
    navEl.classList.toggle("nav__list--active");
}

burgerEl.addEventListener("click", burgerToggle);
const swiper = new Swiper(".swiper", {
    slidesPerView: 3,
    spaceBetween: 38,
    loop: true,
    breakpoints: {
        0: {
            slidesPerView: 1,
            spaceBetween: 15,
        },
        320: {
            slidesPerView: 1,
            spaceBetween: 15,
        },
        491: {
            slidesPerView: 2,
            spaceBetween: 15,
        },
        790: {
            slidesPerView: 3,
            spaceBetween: 20,
        },
        900: {
            spaceBetween: 38,
        },
    },
    navigation: {
        nextEl: ".feedback__btn.swiper-button-next",
        prevEl: ".feedback__btn.swiper-button-prev",
    },
    centeredSlides: true,
});